/* Container: centred column with side padding. */
.container { width: 100%; max-width: var(--content); margin-inline: auto; padding-inline: var(--s5); } /* bare .container; the size classes below override max-width */
.container-text { max-width: calc(var(--measure) + 2 * var(--s5)); }
.container-page { max-width: calc(var(--content) + 2 * var(--s5)); }
.container-full { max-width: none; }

.heading { font-weight: 500; line-height: 1.2; text-wrap: balance; }
.heading-display { font-family: var(--font-display); font-weight: 700; font-size: clamp(1.75rem, 4vw, 2.75rem); letter-spacing: -0.03em; line-height: 0.95; }
.heading-xl { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.heading-lg { font-size: calc(var(--text-lg) * 1.35); }
.heading.heading-md { font-size: var(--text-lg); } /* two classes: typography.css (later in the bundle) also defines .heading-md and .heading-sm with other sizes */
.heading.heading-sm { font-size: var(--text-base); }
/* One casing rule: uppercase and the huge size live on .display / .display-* (the page title) only. Heading size="display" is the h1 of app content: 28px to 44px, sentence case. */

.text { max-width: var(--measure); }
.text-xs { font-size: var(--text-xs); } .text-sm { font-size: var(--text-sm); } .text-md { font-size: var(--text-base); } .text-lg { font-size: var(--text-lg); }
.text-muted { color: var(--muted); } .text-danger { color: var(--danger); } .text-success, .text-ok { color: var(--ok); } .text-warning { color: var(--warning); } .text-accent { color: var(--accent-text); }
.text-truncate { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }

/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 0 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { height: var(--control-sm); padding: 0 12px; font-size: var(--text-xs); }
.btn-lg { height: var(--control-lg); padding: 0 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { height: auto; padding-block: var(--s2); }
.btn-block { width: 100%; }

/* Block: call to action. */
.block-cta { padding-block: var(--s8); }
.block-cta-box { display: flex; flex-direction: column; gap: var(--s5); padding: var(--s6); border: 1px solid var(--foreground); }
.block-cta-copy { display: flex; flex-direction: column; gap: var(--s2); max-width: var(--measure); }
.block-cta-actions { display: flex; flex-wrap: wrap; gap: var(--s3); }
@media (min-width: 760px) {
  .block-cta-box { flex-direction: row; align-items: center; justify-content: space-between; }
  .block-cta-actions { flex-shrink: 0; }
}

usage:
import {BlockCta, Button} from '@monoline/react';

<BlockCta
  title="Start building today"
  description="Install the package and copy your first component."
  actions={<><Button variant="solid">Get started</Button><Button>Read the docs</Button></>}
/>

